-- Preserve the four existing guided practices and the two supplied videos.
INSERT INTO meditation_content ("id","kind","section","title_en","title_hi","description_en","description_hi","preparation_en","preparation_hi","author","video_id","duration_seconds","steps","repeat","published","sort_order",updated_at) VALUES ('8e0bc1a0-6ce8-4000-8000-000000000001','practice','breathing','Gentle breathing','सहज साँसों का अभ्यास','2 minutes · Follow an easy breathing rhythm','2 मिनट · साँसों की सहज लय अपनाएँ','Sit with your back supported. Use the count only if it feels comfortable; keep your breath gentle and do not hold it.','पीठ को सहारा देकर बैठें। गिनती तभी अपनाएँ जब सहज लगे; आराम से साँस लें और साँस न रोकें।','',NULL,120,'[{"title_en":"Breathe in","title_hi":"साँस अंदर लें","instruction_en":"Breathe in gently through your nose. Let your belly move naturally.","instruction_hi":"नाक से धीरे साँस लें। पेट को स्वाभाविक रूप से हिलने दें।","seconds":4},{"title_en":"Breathe out","title_hi":"साँस बाहर छोड़ें","instruction_en":"Let your breath flow out gently through your mouth. Do not force it.","instruction_hi":"मुँह से धीरे साँस बाहर छोड़ें। ज़ोर न लगाएँ।","seconds":4}]'::jsonb,15,true,0,date_trunc('milliseconds',now())) ON CONFLICT (id) DO NOTHING;
INSERT INTO meditation_content ("id","kind","section","title_en","title_hi","description_en","description_hi","preparation_en","preparation_hi","author","video_id","duration_seconds","steps","repeat","published","sort_order",updated_at) VALUES ('8e0bc1a0-6ce8-4000-8000-000000000002','practice','meditation','Breath awareness','साँसों पर ध्यान','3 minutes · Notice your natural breath','3 मिनट · अपनी स्वाभाविक साँसों को महसूस करें','Sit comfortably with your eyes open or softly closed. There is no need to change your breathing.','आराम से बैठें। आँखें खुली रखें या हल्के से बंद करें। साँस लेने का तरीका बदलने की ज़रूरत नहीं है।','',NULL,180,'[{"title_en":"Settle in","title_hi":"आराम से बैठें","instruction_en":"Feel the support of the chair and the contact of your feet with the floor.","instruction_hi":"कुर्सी का सहारा और ज़मीन पर पैरों का स्पर्श महसूस करें।","seconds":30},{"title_en":"Notice your breath","title_hi":"साँसों को महसूस करें","instruction_en":"Notice where you feel each natural breath: your nose, chest or belly.","instruction_hi":"ध्यान दें कि हर साँस नाक, छाती या पेट में कहाँ महसूस होती है।","seconds":60},{"title_en":"Return gently","title_hi":"धीरे से ध्यान वापस लाएँ","instruction_en":"When your mind wanders, notice it without judging and return to the next breath.","instruction_hi":"मन भटके तो खुद को दोष दिए बिना अगली साँस पर ध्यान वापस लाएँ।","seconds":60},{"title_en":"Take your time","title_hi":"अपना समय लें","instruction_en":"Notice the room around you. Move your hands and feet when you are ready.","instruction_hi":"अपने आस-पास के कमरे पर ध्यान दें। तैयार होने पर हाथ-पैर हिलाएँ।","seconds":30}]'::jsonb,1,true,1,date_trunc('milliseconds',now())) ON CONFLICT (id) DO NOTHING;
INSERT INTO meditation_content ("id","kind","section","title_en","title_hi","description_en","description_hi","preparation_en","preparation_hi","author","video_id","duration_seconds","steps","repeat","published","sort_order",updated_at) VALUES ('8e0bc1a0-6ce8-4000-8000-000000000003','practice','meditation','Body scan','शरीर पर ध्यान','5 minutes · Explore how your body feels','5 मिनट · शरीर की संवेदनाओं को महसूस करें','Sit or lie somewhere supported. Notice sensations without trying to change them. Skip any area you prefer.','सहारा लेकर बैठें या लेटें। संवेदनाओं को बदलने की कोशिश किए बिना महसूस करें। चाहें तो किसी हिस्से को छोड़ दें।','',NULL,300,'[{"title_en":"Arrive","title_hi":"वर्तमान में आएँ","instruction_en":"Feel the surface beneath you. Let your breathing find its own rhythm.","instruction_hi":"अपने नीचे की सतह महसूस करें। साँसों को अपनी सहज लय में चलने दें।","seconds":30},{"title_en":"Feet and legs","title_hi":"पैर और टाँगें","instruction_en":"Notice your toes, feet and legs. You may feel warmth, pressure or very little at all.","instruction_hi":"पैरों की उँगलियों, पैरों और टाँगों पर ध्यान दें। गर्माहट, दबाव या बहुत कम संवेदना भी हो सकती है।","seconds":60},{"title_en":"Belly and back","title_hi":"पेट और पीठ","instruction_en":"Bring attention to your belly and back. Notice contact and the movement of breathing.","instruction_hi":"पेट और पीठ पर ध्यान लाएँ। स्पर्श और साँसों की हलचल महसूस करें।","seconds":60},{"title_en":"Hands and shoulders","title_hi":"हाथ और कंधे","instruction_en":"Notice your fingers, arms and shoulders. Let them rest in a comfortable position.","instruction_hi":"उँगलियों, बाँहों और कंधों पर ध्यान दें। इन्हें आरामदायक स्थिति में रहने दें।","seconds":60},{"title_en":"Face and jaw","title_hi":"चेहरा और जबड़ा","instruction_en":"Notice your forehead, eyes and jaw. Allow space for whatever you feel.","instruction_hi":"माथे, आँखों और जबड़े पर ध्यान दें। जो भी महसूस हो, उसे रहने दें।","seconds":60},{"title_en":"Return to the room","title_hi":"आस-पास पर ध्यान लाएँ","instruction_en":"Feel your whole body supported. Look around and move gently when ready.","instruction_hi":"पूरे शरीर को मिले सहारे को महसूस करें। तैयार होने पर आस-पास देखें और धीरे हिलें।","seconds":30}]'::jsonb,1,true,2,date_trunc('milliseconds',now())) ON CONFLICT (id) DO NOTHING;
INSERT INTO meditation_content ("id","kind","section","title_en","title_hi","description_en","description_hi","preparation_en","preparation_hi","author","video_id","duration_seconds","steps","repeat","published","sort_order",updated_at) VALUES ('8e0bc1a0-6ce8-4000-8000-000000000004','practice','grounding','Sense your surroundings','आस-पास को महसूस करें','2 minutes · Bring attention to the present','2 मिनट · वर्तमान पर ध्यान लाएँ','Keep your eyes open in a comfortable, safe place. Use whichever senses are available to you.','आरामदायक, सुरक्षित जगह पर आँखें खुली रखें। जो इंद्रियाँ आपके लिए उपलब्ध हैं, उनका उपयोग करें।','',NULL,120,'[{"title_en":"Look around","title_hi":"आस-पास देखें","instruction_en":"Notice a few things you can see. Explore their colours, shapes and textures.","instruction_hi":"दिखाई देने वाली कुछ चीज़ों पर ध्यान दें। उनके रंग, आकार और बनावट देखें।","seconds":30},{"title_en":"Feel support","title_hi":"सहारा महसूस करें","instruction_en":"Notice your feet on the floor or your hands resting on a surface.","instruction_hi":"ज़मीन पर पैरों या किसी सतह पर टिके हाथों का स्पर्श महसूस करें।","seconds":30},{"title_en":"Listen","title_hi":"सुनें","instruction_en":"Notice nearby or distant sounds. If listening is not comfortable, look at an object instead.","instruction_hi":"पास या दूर की आवाज़ों पर ध्यान दें। सुनना सहज न लगे तो किसी वस्तु को देखें।","seconds":30},{"title_en":"Come back","title_hi":"ध्यान वापस लाएँ","instruction_en":"Notice one detail around you, take a natural breath and choose what to do next.","instruction_hi":"आस-पास की किसी एक बात पर ध्यान दें, स्वाभाविक साँस लें और आगे क्या करना है चुनें।","seconds":30}]'::jsonb,1,true,3,date_trunc('milliseconds',now())) ON CONFLICT (id) DO NOTHING;
INSERT INTO meditation_content ("id","kind","section","title_en","title_hi","description_en","description_hi","preparation_en","preparation_hi","author","video_id","duration_seconds","steps","repeat","published","sort_order",updated_at) VALUES ('8e0bc1a0-6ce8-4000-8000-000000000005','video','affirmations','Affirmations video','सकारात्मक कथनों का वीडियो','','','','','','s2NISyShKXM',NULL,'[]'::jsonb,1,true,15,date_trunc('milliseconds',now())) ON CONFLICT (id) DO NOTHING;
INSERT INTO meditation_content ("id","kind","section","title_en","title_hi","description_en","description_hi","preparation_en","preparation_hi","author","video_id","duration_seconds","steps","repeat","published","sort_order",updated_at) VALUES ('8e0bc1a0-6ce8-4000-8000-000000000006','video','affirmations','Daily morning affirmations · Sandeep Maheshwari','सुबह के सकारात्मक कथन · संदीप माहेश्वरी','','','','','Sandeep Maheshwari','fG1oNm2tCro',NULL,'[]'::jsonb,1,true,16,date_trunc('milliseconds',now())) ON CONFLICT (id) DO NOTHING;
